/**
 * R53 — WHO ACTUALLY OWNS THE READER'S JAVASCRIPT (g18, 2026-08-18).
 *
 * ## What was wrong with the number this replaces
 *
 * `check-build-output.mjs` split the client budget into MapLibre and
 * application by testing whether a chunk's BYTES CONTAIN THE STRING
 * `maplibre`, and attributing the WHOLE chunk when they did. The auditor asked
 * for the two tracked separately for one reason — so map cost cannot hide
 * inside application cost — and a whole-chunk substring test cannot do that
 * job:
 *
 *   - During AUD-03's re-chunking the split moved from 2,155,530 to 1,148,412
 *     while no map code moved at all. A number that redraws itself when chunks
 *     are reshuffled is not measuring the thing it names.
 *   - Measured here on 2026-08-18: of the two chunks flagged MapLibre on `/`,
 *     one is 1,096,720 bytes and one is 51,533 — and the small one is
 *     application code that merely MENTIONS the library.
 *   - This session's own AUD-06 change is the cleanest demonstration. It
 *     touched application modules only. Across three builds the reported
 *     `applicationBytes` was byte-identical at 1,568,189 every time, while
 *     `maplibreBytes` absorbed the entire delta in both directions: 1,148,376
 *     then 1,148,535 (+159) then 1,148,253 (−123). The split reported map
 *     growth for a change that contained no map code.
 *
 * A budget that reports a number nobody can trust is worse than one that
 * reports nothing, because it invites belief. Hence provenance.
 *
 * ## What this measures instead
 *
 * The build's own module graph, read out of its source maps. For each chunk on
 * the route's critical path: follow its `sourceMappingURL` to its map, decode
 * the `mappings` VLQ, and attribute each run of generated bytes to the SOURCE
 * MODULE that produced it. Bytes are then summed by owner — a path under
 * `maplibre-gl` or `mapbox-gl` is the map library, everything else is not.
 *
 * That is provenance, not a text search: it attributes WITHIN a chunk, so
 * re-chunking cannot move it. `tests/build-attribution.test.ts` proves exactly
 * that by planting a re-chunk.
 *
 * ## Three honesty constraints, each of which cost a simpler design
 *
 * 1. **Unmapped bytes are their own bucket, never folded into application.**
 *    A chunk's runtime wrapper and any span the map does not cover belong to
 *    nobody in particular, and silently adding them to application would be
 *    inventing an attribution — the same failure this row exists to fix, one
 *    level down.
 *
 * 2. **Gzip is NOT split.** Compression is not additive: the gzipped size of a
 *    subset of a stream is not a share of the whole, because matches reach
 *    across module boundaries. The old output printed a MapLibre gzip figure
 *    and an application gzip figure, and both were arithmetic on a number that
 *    had no per-module meaning. Raw bytes are attributable; transfer bytes are
 *    reported for the whole route and left there.
 *
 * 3. **A missing map REFUSES.** Source maps are emitted only when
 *    `WTP_ATTRIBUTION_BUILD=1` (see `next.config.ts`), because shipping maps
 *    on every deploy is a real cost paid for a metric. When they are absent
 *    this returns `{ available: false }` and the caller says so. It never
 *    returns zero: a measurement that reads a missing file as 0 bytes passes
 *    loudest exactly when it has stopped working, which is this repo's oldest
 *    recorded lesson.
 */

import { existsSync, readFileSync } from "node:fs";
import { dirname, join } from "node:path";

/** Source paths that ARE the map library. Matched on the module path. */
const MAP_LIBRARY = /(?:^|[/\\])(?:maplibre-gl|mapbox-gl)(?:[/\\@]|$)/i;

const B64 = new Map(
  [..."ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"].map(
    (c, i) => [c, i],
  ),
);

/**
 * Decode one VLQ field, returning the value and the next index.
 *
 * Written out rather than pulled from `@jridgewell/sourcemap-codec`: this
 * script runs in the postbuild path on a machine that has just installed
 * production dependencies, and a budget check that can fail on a missing
 * devDependency is a budget check people learn to skip.
 */
function decodeVlq(str, i) {
  let result = 0;
  let shift = 0;
  let cont = true;
  while (cont) {
    const digit = B64.get(str[i++]);
    if (digit === undefined) return null;
    cont = (digit & 32) !== 0;
    result += (digit & 31) << shift;
    shift += 5;
  }
  const negative = (result & 1) === 1;
  result >>>= 1;
  return { value: negative ? -result : result, next: i };
}

/**
 * Bytes of `code` attributable to each source index, from `mappings`.
 *
 * A segment names a generated column; the bytes it owns run to the NEXT
 * segment's column, or to the end of that generated line. Minified output is a
 * small number of very long lines, which is exactly the shape this handles
 * best — the spans are long and the boundaries are the segment columns.
 *
 * Returns `{ bySource: Map<number, number>, unmapped: number }`. The two plus
 * nothing else sum to `code.length`; the caller asserts that.
 */
export function attributeChunk(code, mappings) {
  const lines = code.split("\n");
  const bySource = new Map();
  let unmapped = 0;
  let sourceIndex = 0;

  /*
   * UTF-8 BYTES, MEASURED, NOT UTF-16 CODE UNITS COUNTED.
   *
   * Source map columns are in UTF-16 code units, and the budget's raw figure
   * is UTF-8 bytes. Counting columns and calling the result bytes is wrong by
   * exactly the multi-byte characters in the bundle — 671 of them on the build
   * this was written against, which is small and is still a number that does
   * not reconcile. Every span is measured with `Buffer.byteLength` so the
   * three buckets sum to the byte total exactly, and the caller asserts it.
   */
  const span = (line, from, to) =>
    from >= to ? 0 : Buffer.byteLength(line.slice(from, to), "utf8");

  const groups = mappings.split(";");
  for (let line = 0; line < lines.length; line++) {
    const text = lines[line];
    // `+1` for the newline that `split` removed, except on the last line.
    const newline = line < lines.length - 1 ? 1 : 0;
    const cols = text.length;
    const group = groups[line];
    if (group === undefined || group === "") {
      unmapped += span(text, 0, cols) + newline;
      continue;
    }

    // Decode this line's segments into (column, sourceIndex) pairs. `sourceIndex`
    // is delta-encoded ACROSS lines, so it is not reset per line; the generated
    // column is reset per line, which is why it is declared here.
    let column = 0;
    const segments = [];
    for (const seg of group.split(",")) {
      if (seg === "") continue;
      let i = 0;
      const col = decodeVlq(seg, i);
      if (!col) continue;
      column += col.value;
      i = col.next;
      const srcDelta = decodeVlq(seg, i);
      if (!srcDelta) {
        // A one-field segment marks generated code with NO source. Recorded as
        // a boundary owned by nobody rather than skipped, so the span before
        // the next segment is not silently credited to the previous module.
        segments.push({ column, source: null });
        continue;
      }
      sourceIndex += srcDelta.value;
      segments.push({ column, source: sourceIndex });
    }
    if (segments.length === 0) {
      unmapped += span(text, 0, cols) + newline;
      continue;
    }

    // Anything before the first segment belongs to nobody. So does the
    // newline: it is generated punctuation, not any module's code.
    unmapped += span(text, 0, Math.min(segments[0].column, cols)) + newline;
    for (let s = 0; s < segments.length; s++) {
      const start = Math.min(segments[s].column, cols);
      const end = Math.min(
        s + 1 < segments.length ? segments[s + 1].column : cols,
        cols,
      );
      const bytes = span(text, start, end);
      if (segments[s].source === null) unmapped += bytes;
      else
        bySource.set(
          segments[s].source,
          (bySource.get(segments[s].source) ?? 0) + bytes,
        );
    }
  }

  return { bySource, unmapped };
}

/** The map a chunk names in its own `sourceMappingURL` comment, or null. */
function mapFor(chunkPath, code) {
  const match = /\/\/#\s*sourceMappingURL=([^\s*]+)\s*$/m.exec(code);
  if (!match) return null;
  const mapPath = join(dirname(chunkPath), match[1]);
  return existsSync(mapPath) ? mapPath : null;
}

/**
 * Attribute a route's initial JavaScript by module provenance.
 *
 * `srcs` are the `/_next/...` script sources the prerendered HTML names — the
 * same list the byte total is measured from, deliberately, so the split and
 * the total can never describe different sets of files.
 */
export function attributeByProvenance({ next, srcs }) {
  let mapLibrary = 0;
  let application = 0;
  let unmapped = 0;
  let total = 0;
  let chunksWithMaps = 0;

  for (const src of srcs) {
    const file = join(next, src.replace(/^\/_next\//, ""));
    if (!existsSync(file)) continue;
    const code = readFileSync(file, "utf8");
    total += Buffer.byteLength(code);

    const mapPath = mapFor(file, code);
    if (!mapPath) {
      // No map for this chunk: its bytes are unattributed, and saying so is
      // the whole point. They are never assumed to be application code.
      unmapped += Buffer.byteLength(code);
      continue;
    }
    chunksWithMaps += 1;

    const map = JSON.parse(readFileSync(mapPath, "utf8"));
    const sources = map.sources ?? [];
    const { bySource, unmapped: chunkUnmapped } = attributeChunk(
      code,
      map.mappings ?? "",
    );
    unmapped += chunkUnmapped;
    for (const [index, bytes] of bySource) {
      const path = sources[index] ?? "";
      if (MAP_LIBRARY.test(path)) mapLibrary += bytes;
      else application += bytes;
    }
  }

  if (chunksWithMaps === 0) {
    return {
      available: false,
      why:
        "no chunk on this route carries a sourceMappingURL — rebuild with " +
        "WTP_ATTRIBUTION_BUILD=1 to emit source maps",
    };
  }

  /*
   * THE RECONCILIATION, ASSERTED RATHER THAN ASSUMED.
   *
   * Three buckets and a total that must agree to the byte. A split that
   * quietly loses bytes is the same class of defect as the one this replaces:
   * a number that looks like a measurement and is not one. If this ever
   * throws, the attribution is wrong and the build says so instead of printing
   * a plausible figure.
   */
  const summed = mapLibrary + application + unmapped;
  if (summed !== total) {
    throw new Error(
      `client attribution does not reconcile: ${mapLibrary} + ${application} + ` +
        `${unmapped} = ${summed}, but the chunks are ${total} bytes ` +
        `(${total - summed} unaccounted)`,
    );
  }

  return {
    available: true,
    chunksWithMaps,
    chunksTotal: srcs.length,
    total,
    mapLibrary,
    application,
    unmapped,
  };
}
